  { f=>[ ["I work at {work}, so I know all the cafés here.","{work} yerinde çalışıyorum, o yüzden buradaki bütün kafeleri bilirim."],
         ["Working at {work} means I have tried every café in {city} by now.","{work} yerinde çalışmak, {city} şehrindeki her kafeyi denemişim demek."] ],
    o=>[ [ ["Do you like your job?","İşini seviyor musun?"], ["Is your job hard?","İşin zor mu?"] ],
         [ ["How long have you worked there?","Ne zamandır orada çalışıyorsun?"], ["When did you start that job?","O işe ne zaman başladın?"] ],
         [ ["That sounds interesting.","Kulağa ilginç geliyor."], ["Lucky you!","Ne şanslısın!"] ] ] },
