         [ ["I stayed at home and watched films.","Evde kalıp film izledim."], ["Nothing special, I relaxed.","Özel bir şey yok, dinlendim."] ] ] },
  { f=>[ ["Look outside. I love {weather}.","Dışarı bak. {weather} bayılırım."],
