         [ ["Very late. About eleven.","Çok geç. On bir gibi."], ["Too late, honestly.","Açıkçası fazla geç."] ],
         [ ["It depends on the day.","Güne göre değişir."], ["Early in the week, late at weekends.","Hafta içi erken, hafta sonu geç."] ] ] },
