         ["I am up early because of {work}. My alarm goes off before the sun.","{work} yüzünden erken kalkıyorum. Alarmım güneşten önce çalıyor."] ],
    o=>[ [ ["That is very early!","Bu çok erken!"], ["I could never do that.","Ben bunu asla yapamam."] ],
         [ ["Do you go to bed early too?","Erken de mi yatıyorsun?"], ["When do you sleep then?","Peki ne zaman uyuyorsun?"] ],
         [ ["Are you tired all the time?","Sürekli yorgun musun?"], ["How do you have energy?","Enerjiyi nereden buluyorsun?"] ] ] },
  { f=>[ ["Coffee helps. I drink {drink} every day.","Kahve yardımcı oluyor. Her gün {drink} içerim."],
         ["Coffee is the answer. I have {drink} every single day, sometimes twice.","Cevap kahve. Her gün {drink} içerim, bazen iki kez."] ],
