         [ ["Is that not too much coffee?","Bu çok fazla kahve değil mi?"], ["Does it keep you awake at night?","Geceleri uyutmuyor mu?"] ],
         [ ["I drink coffee too, three cups.","Ben de kahve içerim, üç fincan."], ["Same here, I love coffee.","Ben de öyle, kahveye bayılırım."] ] ] },
  { f=>[ ["Do you cook at home or eat outside?","Evde mi pişiriyorsun yoksa dışarıda mı yiyorsun?"],
