         [ ["I cannot cook at all.","Hiç yemek yapamam."], ["My cooking is terrible.","Yemeklerim berbat."] ] ] },
  { f=>[ ["My favourite food is {food}. Have you tried it?","En sevdiğim yemek {food}. Hiç denedin mi?"],
         ["If I had to choose one meal forever, it would be {food}. Have you ever tried it?","Ömrüm boyunca tek yemek seçseydim {food} olurdu. Hiç denedin mi?"] ],
    o=>[ [ ["No, but I want to.","Hayır ama denemek isterim."], ["Never. What is in it?","Hiç. İçinde ne var?"] ],
         [ ["Yes! I love it.","Evet! Bayılıyorum."], ["I tried it once, it was good.","Bir kez denedim, güzeldi."] ],
         [ ["My favourite is kebab.","Benim favorim kebap."], ["I prefer soup and bread.","Ben çorba ve ekmeği tercih ederim."] ] ] },
