         [ ["When? I am free on Sunday.","Ne zaman? Pazar günü müsaitim."], ["Give me a day and I am there.","Bir gün söyle, oradayım."] ] ] },
  { f=>[ ["Okay, I have to go to work. See you!","Tamam, işe gitmem lazım. Görüşürüz!"],
