         [ ["Is it long? I am tired.","Uzun mu? Yorgunum."], ["Is it in English? I need subtitles.","İngilizce mi? Altyazı lazım bana."] ] ] },
  { f=>[ ["I also watch {series}. Do you know it?","{series} dizisini de izliyorum. Biliyor musun?"],
         ["I am completely hooked on {series} at the moment. Do you watch it?","Şu an tamamen {series} dizisine takıldım. İzliyor musun?"] ],
    o=>[ [ ["I know it but I have not watched it.","Biliyorum ama izlemedim."], ["I have heard of it.","Adını duydum."] ],
         [ ["Yes! Which season are you on?","Evet! Hangi sezondasın?"], ["I love that show!","O diziye bayılıyorum!"] ],
         [ ["I do not watch series much.","Pek dizi izlemem."], ["I prefer films.","Ben filmleri tercih ederim."] ] ] },
  { f=>[ ["Popcorn? I always eat popcorn with films.","Patlamış mısır? Filmle hep patlamış mısır yerim."],
         ["I will make popcorn. A film without popcorn is not a real film.","Patlamış mısır yapayım. Mısırsız film, film değildir."] ],
    o=>[ [ ["Yes please, with salt.","Evet lütfen, tuzlu olsun."], ["Popcorn sounds perfect.","Patlamış mısır mükemmel olur."] ],
         [ ["No thanks, I just ate.","Yok sağ ol, daha yeni yedim."], ["Maybe later.","Belki sonra."] ],
         [ ["Do you have anything sweet?","Tatlı bir şeyin var mı?"], ["Can I have some water too?","Biraz da su alabilir miyim?"] ] ] },
  { f=>[ ["Wait, this part is the best. Watch!","Dur, en güzel yeri burası. İzle!"],
         ["Shh, shh, this scene coming up is the whole reason I love this.","Şşş, şşş, gelen sahne bunu sevmemin bütün sebebi."] ],
    o=>[ [ ["Okay, I am watching!","Tamam, izliyorum!"], ["Do not tell me what happens!","Ne olacağını söyleme!"] ],
         [ ["I do not understand this part.","Bu kısmı anlamadım."], ["Can you explain that?","Şunu açıklayabilir misin?"] ],
         [ ["Wow, that was good!","Vay, bu iyiydi!"], ["That surprised me!","Beni şaşırttı!"] ] ] },
  { f=>[ ["Do you watch films in English?","Filmleri İngilizce izliyor musun?"],
         ["Do you watch things in English? It helped my friends a lot with the language.","İngilizce izliyor musun? Arkadaşlarıma dil konusunda çok yardımı olmuştu."] ],
    o=>[ [ ["Yes, with subtitles.","Evet, altyazıyla."], ["I try, but it is fast.","Deniyorum ama hızlı konuşuyorlar."] ],
         [ ["No, I watch with dubbing.","Hayır, dublajlı izliyorum."], ["Only in my language.","Sadece kendi dilimde."] ],
         [ ["I understand about half.","Yaklaşık yarısını anlıyorum."], ["I understand more every month.","Her ay biraz daha anlıyorum."] ] ] },
  { f=>[ ["That is good practice. Your English is getting better.","Bu iyi bir pratik. İngilizcen gelişiyor."],
         ["Honestly, that is the best practice there is. Your English has improved a lot.","Cidden, en iyi pratik bu. İngilizcen çok gelişmiş."] ],
    o=>[ [ ["Thank you! I practise every day.","Teşekkürler! Her gün pratik yapıyorum."], ["That is nice to hear.","Bunu duymak güzel."] ],
         [ ["I still make many mistakes.","Hâlâ çok hata yapıyorum."], ["Speaking is hard for me.","Konuşmak benim için zor."] ],
         [ ["Talking with you helps a lot.","Seninle konuşmak çok yardımcı oluyor."], ["You speak slowly, thank you.","Yavaş konuşuyorsun, teşekkürler."] ] ] },
  { f=>[ ["The film finished. Did you like it?","Film bitti. Beğendin mi?"],
         ["And that is the end. So, what did you think of it?","Ve bitti. Ee, nasıl buldun?"] ],
    o=>[ [ ["I loved it!","Bayıldım!"], ["That was really good.","Gerçekten güzeldi."] ],
         [ ["It was a bit slow for me.","Bana biraz yavaş geldi."], ["The ending was strange.","Sonu tuhaftı."] ],
         [ ["I fell asleep in the middle!","Ortasında uyuyakaldım!"], ["Sorry, I missed some parts.","Pardon, bazı kısımları kaçırdım."] ] ] },
  { f=>[ ["It is late. Do you want to stay or go home?","Geç oldu. Kalmak mı istersin, eve gitmek mi?"],
         ["Look at the time. You are welcome to stay, or I can call you a taxi.","Saate bak. İstersen kal, ya da sana taksi çağırayım."] ],
    o=>[ [ ["I should go home. Thank you!","Eve gitmeliyim. Teşekkürler!"], ["I will go, it is late.","Gideyim, geç oldu."] ],
         [ ["Can you call me a taxi?","Bana taksi çağırabilir misin?"], ["How do I get home from here?","Buradan eve nasıl giderim?"] ],
         [ ["Thanks for the film night.","Film gecesi için teşekkürler."], ["Let us do this again!","Bunu tekrar yapalım!"] ] ] }
 ]
