 beats=>[
  { f=>[ ["I need a holiday! Do you want to travel together?","Tatile ihtiyacım var! Birlikte seyahat etmek ister misin?"],
         ["I desperately need a break. How would you feel about travelling together?","Şiddetle bir molaya ihtiyacım var. Birlikte seyahat etmeye ne dersin?"] ],
    o=>[ [ ["Yes! Great idea.","Evet! Harika fikir."], ["I would love to travel with you.","Seninle seyahat etmek isterim."] ],
         [ ["Maybe. Where do you want to go?","Belki. Nereye gitmek istersin?"], ["Depends where. Tell me more.","Nereye olduğuna bağlı. Anlat biraz."] ],
         [ ["I do not have much money.","Pek param yok."], ["Travel is expensive for me.","Seyahat benim için pahalı."] ] ] },
  { f=>[ ["I really want to go to {place}. It is my dream.","Gerçekten {place} gitmek istiyorum. Hayalim."],
         ["The place at the top of my list is {place}. I have wanted to go for years.","Listemin başındaki yer {place}. Yıllardır gitmek istiyorum."] ],
    o=>[ [ ["Why {place}?","Neden {place}?"], ["What is special about it?","Özel olan nesi var?"] ],
         [ ["That sounds amazing!","Kulağa harika geliyor!"], ["I want to go there too!","Ben de oraya gitmek istiyorum!"] ],
         [ ["Is it far from here?","Buradan uzak mı?"], ["How long is the flight?","Uçuş ne kadar sürüyor?"] ] ] },
  { f=>[ ["Last year I went to {lastHol}. It was beautiful.","Geçen yıl {lastHol} gittim. Çok güzeldi."],
         ["My last proper trip was {lastHol} and honestly it was one of the best.","Son doğru düzgün seyahatim {lastHol} idi ve cidden en iyilerindendi."] ],
    o=>[ [ ["Who did you go with?","Kiminle gittin?"], ["Did you go alone?","Yalnız mı gittin?"] ],
         [ ["What did you do there?","Orada ne yaptın?"], ["What was the best part?","En güzel yanı neydi?"] ],
         [ ["I have never been there.","Ben hiç gitmedim."], ["I would like to see photos.","Fotoğrafları görmek isterim."] ] ] },
  { f=>[ ["When can you travel? I am free in summer.","Ne zaman seyahat edebilirsin? Ben yazın müsaitim."],
         ["The main question is timing. My schedule is clearest in the summer.","Asıl soru zamanlama. Programım en çok yazın müsait."] ],
    o=>[ [ ["Summer is good for me too.","Yaz bana da uyar."], ["July or August, maybe.","Belki temmuz ya da ağustos."] ],
         [ ["I can only travel in winter.","Sadece kışın seyahat edebilirim."], ["Autumn is better for me.","Sonbahar benim için daha iyi."] ],
         [ ["I do not know yet.","Henüz bilmiyorum."], ["I need to check with work.","İşle konuşmam lazım."] ] ] },
  { f=>[ ["How many days? One week or two?","Kaç gün? Bir hafta mı iki mi?"],
         ["How long should we go for, realistically? A week feels short to me.","Gerçekçi olarak ne kadar gitmeliyiz? Bir hafta bana kısa geliyor."] ],
    o=>[ [ ["One week is enough.","Bir hafta yeter."], ["Seven days, I think.","Bence yedi gün."] ],
         [ ["Two weeks would be perfect.","İki hafta mükemmel olur."], ["The longer the better!","Ne kadar uzun o kadar iyi!"] ],
         [ ["Just a long weekend for me.","Bana uzun bir hafta sonu yeter."], ["I only have four days.","Sadece dört günüm var."] ] ] },
  { f=>[ ["Hotel or a small flat? What do you prefer?","Otel mi küçük bir daire mi? Sen neyi tercih edersin?"],
         ["Where should we stay? Personally I prefer a small flat to a big hotel.","Nerede kalalım? Şahsen büyük otel yerine küçük bir daireyi tercih ederim."] ],
    o=>[ [ ["A hotel is easier.","Otel daha kolay."], ["I like hotels with breakfast.","Kahvaltılı otelleri severim."] ],
         [ ["A flat is cheaper.","Daire daha ucuz."], ["I prefer a flat with a kitchen.","Mutfaklı bir daireyi tercih ederim."] ],
         [ ["What about a hostel?","Hostele ne dersin?"], ["Something cheap is fine.","Ucuz bir şey olsa yeter."] ] ] },
  { f=>[ ["I use {transport} here, but we will need a plane.","Burada {transport} kullanırım ama uçak gerekecek."],
         ["Around here I just use {transport}, but this time we definitely need to fly.","Burada sadece {transport} kullanırım ama bu gezi için kesin uçmamız gerek."] ],
    o=>[ [ ["I am scared of flying.","Uçmaktan korkuyorum."], ["I do not like planes.","Uçakları sevmiyorum."] ],
         [ ["Flying is fine for me.","Uçmak benim için sorun değil."], ["I love the airport!","Havaalanına bayılırım!"] ],
         [ ["Can we go by train?","Trenle gidebilir miyiz?"], ["A road trip could be fun.","Karayolu gezisi eğlenceli olabilir."] ] ] },
  { f=>[ ["What do you like on holiday? Beach or city?","Tatilde neyi seversin? Sahil mi şehir mi?"],
         ["What is your holiday style? Lying on a beach, or exploring a city all day?","Tatil tarzın nedir? Sahilde yatmak mı, bütün gün şehir gezmek mi?"] ],
    o=>[ [ ["Beach! I want to relax.","Sahil! Dinlenmek istiyorum."], ["Sun, sea and nothing else.","Güneş, deniz ve başka hiçbir şey."] ],
         [ ["City. I like museums.","Şehir. Müzeleri severim."], ["I want to walk and see everything.","Yürüyüp her şeyi görmek isterim."] ],
         [ ["Mountains and nature for me.","Bana dağlar ve doğa."], ["I like quiet places.","Sessiz yerleri severim."] ] ] },
  { f=>[ ["Okay! I will look at prices tonight.","Tamam! Bu akşam fiyatlara bakarım."],
         ["Perfect. Leave it with me, I will look at flights and prices tonight.","Mükemmel. Bana bırak, bu akşam uçuşlara ve fiyatlara bakarım."] ],
    o=>[ [ ["Great, send me the links.","Harika, bana linkleri gönder."], ["Tell me what you find.","Ne bulursan söyle."] ],
         [ ["I will look too.","Ben de bakarım."], ["Let us both search.","İkimiz de arayalım."] ],
         [ ["Do not book anything yet!","Henüz hiçbir şey ayırtma!"], ["Let me check my money first.","Önce paraya bir bakayım."] ] ] },
  { f=>[ ["This is exciting! {phrase}","Bu çok heyecan verici! {phrase}"],
         ["I am genuinely excited now. This is going to be a good one. {phrase}","Şimdi cidden heyecanlandım. Bu güzel olacak. {phrase}"] ],
