         [ ["Let us talk again tomorrow.","Yarın tekrar konuşalım."], ["Message me tonight.","Bu akşam mesaj at."] ],
         [ ["Thank you for planning this.","Bunu planladığın için teşekkürler."], ["You are a good friend, {name}.","İyi bir arkadaşsın {name}."] ] ] }
